نقش سازمانی: مدیر بازرگانی (commercial_director)

درخواست کاربر:
قیمت فروش ما 14% پایین‌تر از مرجع بازار است. ریشهٔ این تخفیف کجاست؟ (مدیر بازرگانی — شرکت سنگ‌آهن گل‌گهر)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "sales_revenue",
      "description": "درآمد فروش به تفکیک مشتری، محصول و ماه",
      "dimensions": [
        "customer",
        "product",
        "month"
      ],
      "measures": [
        "revenue_m_toman",
        "tons",
        "price_per_ton"
      ]
    },
    {
      "dataset": "customer_portfolio",
      "description": "پرتفوی مشتریان: سهم، ریسک، تاریخچه",
      "dimensions": [
        "customer"
      ],
      "measures": [
        "share_pct",
        "payment_days",
        "volume_tons"
      ]
    },
    {
      "dataset": "market_prices",
      "description": "قیمت‌های جهانی و داخلی محصولات معدنی",
      "dimensions": [
        "product",
        "benchmark"
      ],
      "measures": [
        "usd_per_ton",
        "toman_per_ton"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "price_realization",
      "description": "تحقق قیمت نسبت به مرجع",
      "formula": "قیمت فروش واقعی / قیمت مرجع بازار",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "customer_concentration",
      "description": "تمرکز فروش (سهم مشتری اول)",
      "formula": "درآمد بزرگ‌ترین مشتری / درآمد کل",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "فروش کنسانترهٔ مس و سنگ‌آهن به مشتریان داخلی و صادراتی",
    "قراردادهای بلندمدت ۶ تا ۱۲ ماهه با قیمت‌های ثابت/شناور",
    "نرخ ارز و قیمت‌های جهانیLME تأثیر مستقیم بر درآمد دارند"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "price_realization",
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "price_realization": {
    "prev": 100,
    "curr": 86
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "customer_portfolio",
    "filters": {
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "top_customer_share_pct": 35,
  "discount_range": "14% تخفیف از مرجع",
  "note": "مشتری اصلی (35%) قرارداد ۱۲ماهه با قیمت ثابت دارد که از بازار عقب‌تر است"
}

نقش سازمانی: مدیر بازرگانی (commercial_director)

درخواست کاربر:
قرارداد جدید فروش را با قیمت ثابت یا شناور ببندیم؟ مقایسه کن. (مدیر بازرگانی — شرکت مس شهید باهنر)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "contracts",
      "description": "قراردادهای فروش: قیمت، حجم، شرایط",
      "dimensions": [
        "customer",
        "contract_type"
      ],
      "measures": [
        "volume_tons",
        "price_per_ton",
        "delivery_status"
      ]
    },
    {
      "dataset": "market_prices",
      "description": "قیمت‌های جهانی و داخلی محصولات معدنی",
      "dimensions": [
        "product",
        "benchmark"
      ],
      "measures": [
        "usd_per_ton",
        "toman_per_ton"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "price_realization",
      "description": "تحقق قیمت نسبت به مرجع",
      "formula": "قیمت فروش واقعی / قیمت مرجع بازار",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "فروش کنسانترهٔ مس و سنگ‌آهن به مشتریان داخلی و صادراتی",
    "قراردادهای بلندمدت ۶ تا ۱۲ ماهه با قیمت‌های ثابت/شناور",
    "نرخ ارز و قیمت‌های جهانیLME تأثیر مستقیم بر درآمد دارند"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "contracts",
    "filters": {
      "period": "next_quarter"
    }
  }
}

TOOL_OBSERVATION:
{
  "fixed_option": {
    "price_per_ton": 203000.0,
    "revenue_m": 3552
  },
  "floating_option": {
    "price_per_ton": 222524,
    "revenue_m": 3894,
    "volatility_pct": 16
  }
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "price_realization"
    ],
    "period": "last_3_months"
  }
}

TOOL_OBSERVATION:
{
  "realization_trend": [
    0.96,
    0.97,
    0.96
  ]
}

