ریسک‌های اصلی درآمد فروش برای مدیرعامل را خلاصه کن. (مدیر بازرگانی — مجتمع مس سونگون)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "sales_revenue",
      "description": "درآمد فروش به تفکیک مشتری، محصول و ماه",
      "dimensions": [
        "customer",
        "product",
        "month"
      ],
      "measures": [
        "revenue_m_toman",
        "tons",
        "price_per_ton"
      ]
    },
    {
      "dataset": "customer_portfolio",
      "description": "پرتفوی مشتریان: سهم، ریسک، تاریخچه",
      "dimensions": [
        "customer"
      ],
      "measures": [
        "share_pct",
        "payment_days",
        "volume_tons"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "revenue_per_ton",
      "description": "میانگین قیمت فروش هر تن",
      "formula": "درآمد کل / تن فروخته‌شده",
      "unit": "میلیون تومان بر تن",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "customer_concentration",
      "description": "تمرکز فروش (سهم مشتری اول)",
      "formula": "درآمد بزرگ‌ترین مشتری / درآمد کل",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "dso",
      "description": "دورهٔ وصول مطالبات",
      "formula": "مطالبات / (درآمد سالانه / ۳۶۵)",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "فروش کنسانترهٔ مس و سنگ‌آهن به مشتریان داخلی و صادراتی",
    "قراردادهای بلندمدت ۶ تا ۱۲ ماهه با قیمت‌های ثابت/شناور",
    "نرخ ارز و قیمت‌های جهانیLME تأثیر مستقیم بر درآمد دارند"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "revenue_per_ton",
      "customer_concentration",
      "dso"
    ],
    "period": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "revenue_per_ton_m": 0.08,
  "customer_concentration_pct": 34,
  "dso_days": 65
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "sales_revenue",
    "filters": {
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "total_revenue_m": 1141,
  "risks": [
    "تمرکز بالا روی مشتری اول",
    "DSO بالا",
    "وابستگی به نرخ ارز"
  ]
}

نقش سازمانی: مدیر بازرگانی (commercial_director)

درخواست کاربر:
تفاوت عملکرد فروش داخلی و صادراتی این ماه چیست؟ آیا صادرات به‌صرفه‌تر است؟ (مدیر بازرگانی — مجتمع مس سرچشمه)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "sales_revenue",
      "description": "درآمد فروش به تفکیک مشتری، محصول و ماه",
      "dimensions": [
        "customer",
        "product",
        "month"
      ],
      "measures": [
        "revenue_m_toman",
        "tons",
        "price_per_ton"
      ]
    },
    {
      "dataset": "export_logistics",
      "description": "صادرات: حجم، مقصد، هزینهٔ حمل",
      "dimensions": [
        "destination",
        "month"
      ],
      "measures": [
        "tons",
        "revenue_m_toman",
        "logistics_cost"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "export_share",
      "description": "سهم صادرات از کل فروش",
      "formula": "درآمد صادراتی / درآمد کل",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "revenue_per_ton",
      "description": "میانگین قیمت فروش هر تن",
      "formula": "درآمد کل / تن فروخته‌شده",
      "unit": "میلیون تومان بر تن",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "فروش کنسانترهٔ مس و سنگ‌آهن به مشتریان داخلی و صادراتی",
    "قراردادهای بلندمدت ۶ تا ۱۲ ماهه با قیمت‌های ثابت/شناور",
    "نرخ ارز و قیمت‌های جهانیLME تأثیر مستقیم بر درآمد دارند"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "export_share",
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "export_share": {
    "prev": 35,
    "curr": 42
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "sales_revenue",
    "filters": {
      "period": "this_month",
      "split": "domestic_export"
    }
  }
}

TOOL_OBSERVATION:
{
  "domestic": {
    "revenue_m": 552,
    "tons": 55200,
    "price_m_per_ton": 0.01
  },
  "export": {
    "revenue_m": 404,
    "tons": 40400,
    "price_m_per_ton": 0.01
  }
}

